'use strict';
const $ = (s,root=document) => root.querySelector(s);
const $$ = (s,root=document) => [...root.querySelectorAll(s)];
const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;
const sources = {
  poem: 'https://www.elbrusoid.net/articles/abiyat/358978/',
  portrait: 'https://www.kbpravda.ru/node/2225',
  biography: 'https://www.smikbr.ru/node/12223',
  poemsRu: 'https://www.goryankakbr.ru/node/679',
  books: 'https://gvardiya.ru/books/zhizn-zamechatelnyh-lyudey/kerim-otarov'
};
const words = [
  {word:'Тау',translation:'Гора',description:'Слово, с которого начинается знакомство с горным миром карачаево-балкарского языка.'},
  {word:'Жюрек',translation:'Сердце',description:'Сердце — и как часть тела, и как образ внутренней жизни человека.'},
  {word:'Жол',translation:'Дорога, путь',description:'Путь, по которому идут. В поэзии дорога может становиться образом человеческой судьбы.'},
  {word:'Тил',translation:'Язык',description:'Язык, на котором говорят, думают и передают память следующим поколениям.'},
  {word:'Жарыкъ',translation:'Свет; светлый',description:'Свет и светлое состояние. Значение уточняется в контексте строки.'},
  {word:'Туугъан жерим',translation:'Моя родная земля',description:'Туугъан жер — родная земля, место рождения. Форма жерим означает «моя земля».'}
];
function readStorage(key,fallback){try {const value=localStorage.getItem(key); return value?JSON.parse(value):fallback;}catch{return fallback;}}
function writeStorage(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{toast('Браузер не разрешил сохранение.');return false;}}
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function openDialog(dialog){if(!dialog.open)dialog.showModal();document.body.classList.add('modal-open');}
function syncDialogLock(){document.body.classList.toggle('modal-open',$$('dialog[open]').length>0);}
$$('.close-dialog').forEach(button=>button.addEventListener('click',()=>button.closest('dialog').close()));
$$('dialog').forEach(dialog=>{dialog.addEventListener('close',syncDialogLock);dialog.addEventListener('click',event=>{if(event.target===dialog&&dialog.id==='info-dialog'){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});});
const menuButton=$('#menu-toggle'), mobileNav=$('#mobile-nav');
function closeMenu(){menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Открыть меню');mobileNav.classList.remove('open');mobileNav.inert=true;document.body.style.overflow='';}
menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'Закрыть меню':'Открыть меню');mobileNav.classList.toggle('open',open);mobileNav.inert=!open;document.body.style.overflow=open?'hidden':'';});
$$('a',mobileNav).forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeMenu();});
matchMedia('(min-width: 761px)').addEventListener('change',event=>{if(event.matches)closeMenu();});
const quotes=['«Я горд своей<br>дорогою земной…»','«Туугъан жерим!<br>Сени кёрмей къалырда…»','«Но жили с верой<br>до последних дней».'];
let currentPoem=0,lastScrollPoem=0,quoteTimer;
function setPoem(index){if(index===currentPoem)return;currentPoem=index;clearTimeout(quoteTimer);const quote=$('#hero-quote');quote.classList.add('switching');quoteTimer=setTimeout(()=>{quote.innerHTML=quotes[index];quote.lang=index===1?'krc':'ru';quote.classList.remove('switching');},reducedMotion?0:220);$('#poem-number').textContent=`0${index+1} — 03`;$$('[data-poem]').forEach(button=>{const active=Number(button.dataset.poem)===index;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});}
$$('[data-poem]').forEach(button=>button.addEventListener('click',()=>setPoem(Number(button.dataset.poem))));
let framePending=false;
function updateScroll(){framePending=false;const hero=$('.hero-scroll'),stage=$('.hero-stage');const available=hero.offsetHeight-stage.offsetHeight;const progress=Math.max(0,Math.min(1,-hero.getBoundingClientRect().top/Math.max(1,available)));const next=Math.min(2,Math.floor(progress*3));if(next!==lastScrollPoem){lastScrollPoem=next;setPoem(next);}if(!reducedMotion)$('.portrait-wrap').style.transform=`scale(${1+progress*.045})`;$('.hero-progress').style.width=`${progress*100}%`;$('#header').classList.toggle('scrolled',scrollY>stage.offsetHeight*.85);}
addEventListener('scroll',()=>{if(!framePending){framePending=true;requestAnimationFrame(updateScroll);}}, {passive:true});addEventListener('resize',updateScroll);updateScroll();
if('IntersectionObserver' in window){document.body.classList.add('js-ready');const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target);}}),{threshold:.07});$$('.reveal').forEach(el=>observer.observe(el));}
const wave=$('.waveform');for(let i=0;i<100;i++){const bar=document.createElement('i');bar.style.height=`${10+(Math.sin(i*1.71)*.5+.5)*(Math.cos(i*.23)*.3+.7)*90}%`;wave.append(bar);}
let activeFilter='all';
function filterLibrary(){const term=$('#library-search').value.trim().toLocaleLowerCase('ru');let count=0;$$('.book-card').forEach(card=>{const matches=(activeFilter==='all'||card.dataset.kind===activeFilter)&&card.dataset.title.toLocaleLowerCase('ru').includes(term);card.hidden=!matches;if(matches){count++;card.classList.add('visible');}});$('#library-empty').hidden=count>0;}
$$('[data-filter]').forEach(button=>button.addEventListener('click',()=>{activeFilter=button.dataset.filter;$$('[data-filter]').forEach(b=>{const active=b===button;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});filterLibrary();}));
$('#library-search').addEventListener('input',filterLibrary);
$('#search-open').addEventListener('click',()=>{closeMenu();$('#library').scrollIntoView({behavior:reducedMotion?'instant':'smooth'});$('#library-search').focus({preventScroll:true});});
const collections={
 land:{title:'Родная земля',eyebrow:'КЕРИМ ОТАРОВ / ПОЭЗИЯ / 1960',text:'Сборник стихов Керима Отарова. В полном архиве здесь появятся оглавление, тексты на родном языке и проверенные переводы.',source:'https://ru.wikipedia.org/wiki/Отаров,_Керим_Сарамурзаевич'},
 star:{title:'Моя утренняя звезда',eyebrow:'КЕРИМ ОТАРОВ / ПОЭЗИЯ / 1969',text:'Лирический сборник поэта. Макет показывает будущую структуру библиотеки; полный текст издания здесь пока не опубликован.',source:'https://ru.wikipedia.org/wiki/Отаров,_Керим_Сарамурзаевич'},
 hero:{title:'Герой нашего времени',eyebrow:'МИХАИЛ ЛЕРМОНТОВ / ПЕРЕВОДЫ',text:'Раздел для перевода Керима Отарова, предложенный в задании. Для публикации нужно сверить текст с конкретным изданием. Сам перевод в этом макете не воспроизведён.',source:'https://www.elbrusoid.net/library/'}
};
function showInfo(html){$('#info-content').innerHTML=html;openDialog($('#info-dialog'));$('#info-dialog').scrollTop=0;}
function openReader(){
 $('#reader-title').textContent='Сокъур болур эдим';$('#reader-eyebrow').textContent='ОТАРЛАНЫ КЕРИМ / 1955';$('#reader-subtitle').textContent='Короткий фрагмент · оригинал и пояснительный подстрочник';
 $('.original-column').hidden=false;$('.original-column').innerHTML='<span class="eyebrow">КАРАЧАЕВО-БАЛКАРСКИЙ / ОРИГИНАЛ</span><div class="poem-text original-poem" lang="krc"><button class="poem-word" data-dictionary-word="5">Туугъан жерим!</button> Сени кёрмей къалырда,\nБушуудан къара сокъур болур эдим.</div><p class="editorial-note">Нажмите на подчёркнутое выражение, чтобы открыть его значение.</p>';
 $('#reading-language').textContent='РУССКИЙ / ПОДСТРОЧНИК';$('#reading-poem').textContent='Родная земля! Если бы я\nбольше тебя не увидел,\nот горя я бы ослеп.';
 $('#reader-note').textContent='Пояснительный подстрочник для макета, не опубликованный литературный перевод. Показаны первые две строки стихотворения.';
 $('#context-note').textContent='В публикации стихотворение датировано 1955 годом. Это период ссылки балкарского народа. Обращение к родной земле помогает услышать личное переживание за историческим событием.';
 $('#reader-source').href=sources.poem;$('.reading-text').classList.add('parallel');$('#parallel-toggle').setAttribute('aria-pressed','true');$('#reader-notes').hidden=false;$('.reading-layout').classList.remove('without-notes');$('#notes-toggle').setAttribute('aria-pressed','true');updateSaved();renderComments();openDialog($('#reader'));$('#reader').scrollTop=0;
}
document.addEventListener('click',event=>{const bookButton=event.target.closest('[data-book]');if(bookButton){const id=bookButton.dataset.book;if(id==='roads'){openReader();}else{const book=collections[id];showInfo(`<span class="eyebrow">${book.eyebrow}</span><h2>${book.title}</h2><p>${book.text}</p><span class="status-label">КАРТОЧКА ИЗДАНИЯ / МАКЕТ</span><a href="${book.source}" target="_blank" rel="noopener">Открыть источник ↗</a><button class="solid-button" id="try-reading">Попробовать интерактивное чтение ↗</button>`);$('#try-reading').addEventListener('click',()=>{$('#info-dialog').close();openReader();});}}const wordButton=event.target.closest('[data-dictionary-word]');if(wordButton)openWord(Number(wordButton.dataset.dictionaryWord));});
$('#parallel-toggle').addEventListener('click',()=>{const parallel=!$('.reading-text').classList.contains('parallel');$('.reading-text').classList.toggle('parallel',parallel);$('.original-column').hidden=!parallel;$('#parallel-toggle').setAttribute('aria-pressed',String(parallel));});
$('#notes-toggle').addEventListener('click',()=>{const visible=$('#reader-notes').hidden;$('#reader-notes').hidden=!visible;$('#notes-toggle').setAttribute('aria-pressed',String(visible));$('.reading-layout').classList.toggle('without-notes',!visible);});
function updateSaved(){const saved=readStorage('otarov-saved-poem',false);$('#reader-save').setAttribute('aria-pressed',String(saved));$('#reader-save').innerHTML=saved?'Сохранено <span>✓</span>':'Сохранить <span>♧</span>';}
$('#reader-save').addEventListener('click',()=>{const saved=!readStorage('otarov-saved-poem',false);if(writeStorage('otarov-saved-poem',saved)){updateSaved();toast(saved?'Стихотворение сохранено в этом браузере':'Стихотворение удалено из сохранённого');}});
function renderComments(){const comments=readStorage('otarov-comments',[]);const container=$('#saved-comments');container.replaceChildren();if(!Array.isArray(comments))return;comments.slice(-10).forEach(comment=>{if(!comment||typeof comment.text!=='string')return;const item=document.createElement('div');item.className='saved-comment';item.append(document.createTextNode(comment.text));const label=document.createElement('small');label.textContent='ЛИЧНАЯ ЗАМЕТКА';item.append(label);container.append(item);});}
$('#comment-form').addEventListener('submit',event=>{event.preventDefault();const input=$('#comment-text'),text=input.value.trim();if(!text){input.focus();return;}const old=readStorage('otarov-comments',[]);const comments=Array.isArray(old)?old:[];comments.push({text:text.slice(0,600)});if(writeStorage('otarov-comments',comments.slice(-30))){renderComments();input.value='';toast('Ваша заметка сохранена');}});
const timeline={1912:'Начало пути. Родился в балкарском ауле Гюрхожан у подножия Эльбруса.',1938:'Вышел сборник «Стихи и песни». Керим Отаров возглавил Союз писателей Кабардино-Балкарии.',1944:'Вместе с балкарским народом оказался в ссылке. Годы изгнания провёл в Киргизии.',1956:'Вернулся в Нальчик. Вышел сборник «Дороги»; начался новый этап литературной работы.'};
$$('[data-year]').forEach(button=>button.addEventListener('click',()=>{$$('[data-year]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});$('#timeline-year').textContent=button.dataset.year;$('#timeline-text').textContent=timeline[button.dataset.year];}));
$$('[data-word]').forEach(button=>button.addEventListener('click',()=>{const index=Number(button.dataset.word),word=words[index];$('#word-title').textContent=word.word;$('#word-translation').textContent=word.translation;$('#word-description').textContent=word.description;$('#word-index').textContent=`0${index+1} / 05`;$$('[data-word]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});}));
function openWord(index){const word=words[index];showInfo(`<span class="eyebrow">ЯЗЫК ПОЭЗИИ / СЛОВАРЬ</span><h2 class="word-modal-title" lang="krc">${word.word}</h2><p class="word-modal-translation">${word.translation}</p><p>${word.description}</p><span class="status-label">КРАТКОЕ ПОЯСНЕНИЕ К ТЕКСТУ</span>`);}
const media={author:{eyebrow:'АУДИОБИБЛИОТЕКА / АРХИВ',title:'Голос Керима Отарова',text:'Здесь можно будет слушать стихи в исполнении самого автора и следить за текстом. Архивная запись для этого макета не предоставлена, поэтому воспроизведение пока недоступно.',status:'ОЖИДАЕТ АРХИВНОЙ ЗАПИСИ'},readers:{eyebrow:'АУДИОБИБЛИОТЕКА / СЕГОДНЯ',title:'Новые голоса. Знакомые строки.',text:'Будущий раздел современных чтений: выбор исполнителя, оригинала или перевода и переход от звучащей строки к тексту. Демонстрационные аудиодорожки не подменяют чтение поэта.',status:'КОЛЛЕКЦИЯ ГОТОВИТСЯ'},video:{eyebrow:'ВИДЕОБИБЛИОТЕКА',title:'Память в кадре',text:'Будущий раздел документальных фильмов, выступлений и встреч. Пока можно познакомиться с материалом о презентации новых изданий произведений поэта.',status:'АРХИВ ВИДЕОМАТЕРИАЛОВ'}};
$$('[data-media]').forEach(button=>button.addEventListener('click',()=>{const item=media[button.dataset.media];showInfo(`<span class="eyebrow">${item.eyebrow}</span><h2>${item.title}</h2><p>${item.text}</p><span class="status-label">${item.status}</span><a href="${sources.biography}" target="_blank" rel="noopener">О поэте и его наследии — Портал СМИ КБР ↗</a>`);}));
const demoEvents=[{id:'reading',year:2026,month:10,day:14,time:'19:00',type:'ЛИТЕРАТУРНЫЙ ВЕЧЕР',title:'Когда стихи звучат голосом',place:'Нальчик · место уточняется',description:'Пример литературной встречи: чтение произведений поэта и разговор с читателями.'},{id:'language',year:2026,month:10,day:21,time:'16:00',type:'ОТКРЫТАЯ ЧИТКА',title:'Поэзия на двух языках',place:'Онлайн · пример встречи',description:'Пример встречи о параллельном чтении: родной язык, подстрочник и литературный перевод.'},{id:'memory',year:2026,month:11,day:12,time:'18:00',type:'РАЗГОВОР О НАСЛЕДИИ',title:'Человек за строками',place:'Нальчик · место уточняется',description:'Пример беседы о жизни Керима Отарова, его литературном окружении и памяти о поэте.'}];
let selectedMonth=new Date(2026,10,1);
const months=['янв','фев','мар','апр','май','июн','июл','авг','сен','окт','ноя','дек'];
function renderEvents(){const label=new Intl.DateTimeFormat('ru-RU',{month:'long',year:'numeric'}).format(selectedMonth).replace(' г.','');$('#month-label').textContent=label.charAt(0).toUpperCase()+label.slice(1);const matches=demoEvents.filter(e=>e.year===selectedMonth.getFullYear()&&e.month===selectedMonth.getMonth());$('#events-list').replaceChildren();$('#events-empty').hidden=matches.length>0;matches.forEach(event=>{const row=document.createElement('article');row.className='event-row';row.innerHTML=`<div class="event-date"><strong>${event.day}</strong><span>${months[event.month]}<br>${event.time}</span></div><div class="event-info"><span>${event.type}</span><h3>${event.title}</h3></div><div class="event-place">${event.place}</div><button aria-label="Подробнее: ${event.title}" data-event="${event.id}">↗</button>`;$('#events-list').append(row);});}
$('#month-prev').addEventListener('click',()=>{selectedMonth.setMonth(selectedMonth.getMonth()-1);renderEvents();});$('#month-next').addEventListener('click',()=>{selectedMonth.setMonth(selectedMonth.getMonth()+1);renderEvents();});$('#events-reset').addEventListener('click',()=>{selectedMonth=new Date(2026,10,1);renderEvents();});
$('#events-list').addEventListener('click',event=>{const button=event.target.closest('[data-event]');if(!button)return;const item=demoEvents.find(e=>e.id===button.dataset.event);showInfo(`<span class="eyebrow">АФИША / ${item.type}</span><h2>${item.title}</h2><p>${new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',year:'numeric'}).format(new Date(item.year,item.month,item.day)).replace(' г.','')} · ${item.time} МСК</p><p>${item.description}</p><p>${item.place}</p><span class="status-label">ДЕМОНСТРАЦИОННОЕ СОБЫТИЕ</span><p>Это пример работы афиши, а не анонс подтверждённого мероприятия.</p><button class="solid-button" id="event-calendar">Скачать пример в календарь ↗</button>`);$('#event-calendar').addEventListener('click',()=>downloadCalendar(item));});
function downloadCalendar(item){const stamp=date=>date.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z/,'Z');const start=new Date(Date.UTC(item.year,item.month,item.day,Number(item.time.split(':')[0])-3));const end=new Date(start.getTime()+90*60*1000);const ics=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Kerim Otarov//Design Concept//RU','BEGIN:VEVENT',`UID:demo-${item.id}-2026@kerim-otarov-archive`,`DTSTAMP:${stamp(new Date())}`,`DTSTART:${stamp(start)}`,`DTEND:${stamp(end)}`,`SUMMARY:Пример — ${item.title}`,`DESCRIPTION:Демонстрационное событие макета. Не является реальным анонсом.`,`LOCATION:${item.place}`,'END:VEVENT','END:VCALENDAR'].join('\r\n');const url=URL.createObjectURL(new Blob([ics],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`otarov-demo-${item.id}.ics`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Демонстрационное событие скачано');}
renderEvents();
$('#sources-open').addEventListener('click',()=>showInfo(`<span class="eyebrow">ОБ АРХИВЕ</span><h2>Бережно<br>к живому слову.</h2><p>Это интерактивная дизайн-концепция будущего литературного архива Керима Отарова. Обложки созданы для макета и не являются фотографиями изданий. Комментарии сохраняются только в вашем браузере.</p><p>Оригинал короткого стихотворного фрагмента взят из публикации «Эльбрусоида». Русский подстрочник составлен для демонстрации, его необходимо сверить с редактором перед публикацией. Аудиозаписи не загружены. События афиши — примеры.</p><h3>Источники</h3><a href="${sources.portrait}" target="_blank" rel="noopener">Архивный портрет — «Кабардино-Балкарская правда» ↗</a><a href="${sources.poem}" target="_blank" rel="noopener">Стихи на родном языке — «Эльбрусоид» ↗</a><a href="${sources.poemsRu}" target="_blank" rel="noopener">Русские строки — газета «Горянка» ↗</a><a href="${sources.biography}" target="_blank" rel="noopener">Биография и новые издания — Портал СМИ КБР ↗</a><a href="${sources.books}" target="_blank" rel="noopener">Книга о Кериме Отарове — «Молодая гвардия» ↗</a>`));

$('.reader-brand').addEventListener('click',()=>$('#reader').close());
